contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 artId, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // Initialize c: msg.sender (this contract) becomes the phi factory.
        c.initialize(1, 2, "vt", address(this));

        uint256 before = c.tokenIdCounter();
        uint256 balBefore = address(this).balance;

        uint256 r = c.createArtFromFactory{value: amount}(artId);

        uint256 tokenId = c.getTokenIdFromFactoryArtId(artId);
        uint256 backArtId = c.getFactoryArtId(r);
        uint256 counterAfter = c.tokenIdCounter();
        uint256 balAfter = address(this).balance;

        assert(
            before != 0
                && r == before
                && tokenId == r
                && backArtId == artId
                && counterAfter == before + 1
                && balAfter == balBefore
        );
    }

    fallback() external payable {
        // c treats this contract as IPhiFactory; artCreateFee() must return 0
        // so createArtFromFactory succeeds and refunds the full msg.value.
        assembly {
            mstore(0x00, 0)
            return(0x00, 0x20)
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 chainId,
        uint256 credId,
        string memory vType,
        address feeDest,
        uint256 chainId2,
        uint256 credId2,
        string memory vType2,
        address feeDest2
    ) public {
        require(feeDest != address(0));

        // Fresh contract: initialize once with the first set of arguments.
        c.initialize(chainId, credId, vType, feeDest);

        uint256 ownerBefore = uint256(uint160(address(this)));

        // Any second initialization must revert, regardless of the arguments.
        bool reverted;
        try c.initialize(chainId2, credId2, vType2, feeDest2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.tokenIdCounter() == 1 && c.credId() == credId && c.credChainId() == chainId);
    }

    receive() external payable {}

    fallback() external payable {
        assembly {
            mstore(0x00, 0)
            return(0x00, 0x20)
        }
    }
}

