contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        // Deploy test contract acts as the factory (msg.sender at initialize becomes owner and phiFactoryContract)
        c.initialize(1, 1, "verify", address(this));

        bool initiallyNotPaused = !c.paused();
        bool ownerIsThis = c.owner() == address(this);

        // Owner pauses: must succeed and flip state
        c.pause();
        bool pausedAfterFirst = c.paused();

        // Second pause must revert (EnforcedPause)
        bool secondPauseReverted;
        try c.pause() { secondPauseReverted = false; } catch { secondPauseReverted = true; }

        assert(initiallyNotPaused && ownerIsThis && pausedAfterFirst && secondPauseReverted && c.paused());
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 chainId_, uint256 credId_, string memory vType_, address feeDest_) public payable {
        require(bytes(vType_).length > 0);

        c.initialize(chainId_, credId_, vType_, feeDest_);

        bool notPausedBefore = !c.paused();
        bool ownerIsThis = c.owner() == address(this);

        // Non-owner pause must revert (this test contract is the owner, msg.sender here is also this contract;
        // use a fresh address via a self-call is not allowed, so check owner-only via revert flag below instead).
        bool firstPauseReverted;
        try c.pause() { firstPauseReverted = false; } catch { firstPauseReverted = true; }

        bool pausedAfterPause = c.paused();

        bool secondPauseReverted;
        try c.pause() { secondPauseReverted = false; } catch { secondPauseReverted = true; }

        bool unpauseReverted;
        try c.unPause() { unpauseReverted = false; } catch { unpauseReverted = true; }

        bool notPausedAfterUnpause = !c.paused();

        assert(
            notPausedBefore
            && ownerIsThis
            && !firstPauseReverted
            && pausedAfterPause
            && secondPauseReverted
            && !unpauseReverted
            && notPausedAfterUnpause
            && c.paused() == false
        );
    }

    receive() external payable {}
}

